import{_ as e}from"./chunks/teek.D2koXTAK.js";import{o as i,c as l,aj as o}from"./chunks/vue-vendor.D7waMIYK.js";const k=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":null}'),t={name:"faq.md"};function d(s,a,c,r,n,h){return i(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="插件没有出现在「更多」里" tabindex="-1">插件没有出现在「更多」里 <a class="header-anchor" href="#插件没有出现在「更多」里" aria-label="Permalink to &quot;插件没有出现在「更多」里&quot;">​</a></h2><ol><li>打开「更多 → 插件」，确认状态不是「已禁用」。</li><li>确认插件目录是 <code>.tcl/plugins/&lt;id&gt;/</code>，且里面有 <code>plugin.json</code> 和 <code>main</code> 指向的 jar。</li><li>看 <code>.tcl/log/launcher.log</code> 是否有 <code>[插件][&lt;id&gt;] 加载失败</code> 及异常堆栈。</li><li>点「刷新」重新扫描。插件是在启动器显示后异步加载的，首次进入可能还没加载完。</li></ol><h2 id="导入-zip-失败" tabindex="-1">导入 zip 失败 <a class="header-anchor" href="#导入-zip-失败" aria-label="Permalink to &quot;导入 zip 失败&quot;">​</a></h2><ul><li>zip 根目录必须直接包含 <code>plugin.json</code>，不能再套一层文件夹。</li><li>单个插件最多 4096 个文件、解压后不超过 512 MB。</li><li>路径中不能出现 <code>..</code>，否则会被拒绝。</li><li>清单里的 <code>id</code> 只能使用字母、数字、点、下划线和短横线。</li></ul><h2 id="提示「缺少-main-类」" tabindex="-1">提示「缺少 main 类」 <a class="header-anchor" href="#提示「缺少-main-类」" aria-label="Permalink to &quot;提示「缺少 main 类」&quot;">​</a></h2><p><code>plugin.json</code> 的 <code>main</code> 是完整类名，不是文件名：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;main&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.MyPlugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>类必须 <code>implements TcraftPlugin</code>，并且是 <code>public</code>、有无参构造函数。</p><h2 id="提示-java-版本不兼容" tabindex="-1">提示 Java 版本不兼容 <a class="header-anchor" href="#提示-java-版本不兼容" aria-label="Permalink to &quot;提示 Java 版本不兼容&quot;">​</a></h2><p>插件 jar 必须用 Java 17 编译：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">javac</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 17</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TCraftLauncher.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/com/example/MyPlugin.java</span></span></code></pre></div><p>用 JDK 21/25 编译但指定 <code>--release 17</code> 也可以；不要用 <code>--release 21</code>。</p><h2 id="插件加载了但页面是空白" tabindex="-1">插件加载了但页面是空白 <a class="header-anchor" href="#插件加载了但页面是空白" aria-label="Permalink to &quot;插件加载了但页面是空白&quot;">​</a></h2><ul><li>builder 返回 <code>null</code> 是正常的，内容通过 <code>view.add(...)</code> 添加。</li><li>确认没有在 builder 里抛出异常；异常会显示在日志里。</li><li>不要复用已经属于其他父节点的 Node，JavaFX 会抛 <code>IllegalArgumentException</code>。</li><li>页面每次打开都会重建，状态请放进字段或 <code>Storage</code>。</li></ul><h2 id="修改代码后没有生效" tabindex="-1">修改代码后没有生效 <a class="header-anchor" href="#修改代码后没有生效" aria-label="Permalink to &quot;修改代码后没有生效&quot;">​</a></h2><p>「更多 → 插件」里点「重载」，或禁用再启用。重载会创建新的类加载器， 静态字段会被重置。</p><h2 id="删除插件提示文件被占用" tabindex="-1">删除插件提示文件被占用 <a class="header-anchor" href="#删除插件提示文件被占用" aria-label="Permalink to &quot;删除插件提示文件被占用&quot;">​</a></h2><p>Windows 下 jar 被类加载器持有句柄时无法删除。先禁用插件，再删除； 启动器会把文件移入回收站，失败时会提示具体文件。</p><h2 id="插件能访问哪些文件" tabindex="-1">插件能访问哪些文件 <a class="header-anchor" href="#插件能访问哪些文件" aria-label="Permalink to &quot;插件能访问哪些文件&quot;">​</a></h2><p>插件运行在启动器进程内，拥有和启动器相同的文件权限，没有沙箱。 请只读写自己的数据目录和用户明确选择的文件，不要修改启动器自身文件。 安装第三方插件前请确认来源可信，插件页会显示安全提示。</p><h2 id="插件可以依赖其他库吗" tabindex="-1">插件可以依赖其他库吗 <a class="header-anchor" href="#插件可以依赖其他库吗" aria-label="Permalink to &quot;插件可以依赖其他库吗&quot;">​</a></h2><p>可以。把依赖一起打进插件 jar（fat jar），或作为独立 jar 放在插件目录根部 / <code>lib/</code>。 多个插件使用不同版本的同一库时，类加载器按插件隔离，互不影响。 JavaFX 本身由启动器提供，不要把 JavaFX 打进插件。</p><h2 id="支持-fxml-和-webview-吗" tabindex="-1">支持 FXML 和 WebView 吗 <a class="header-anchor" href="#支持-fxml-和-webview-吗" aria-label="Permalink to &quot;支持 FXML 和 WebView 吗&quot;">​</a></h2><p>默认只加载 <code>javafx.controls</code>、<code>javafx.graphics</code>、<code>javafx.media</code>，不含 <code>javafx.fxml</code> 和 <code>javafx.web</code>。 需要这些模块请联系启动器作者，或在插件内用纯 Java 构建界面。</p><h2 id="图标不显示" tabindex="-1">图标不显示 <a class="header-anchor" href="#图标不显示" aria-label="Permalink to &quot;图标不显示&quot;">​</a></h2><ul><li>内置图标名必须是启动器 <code>res/icons/lucide</code> 中存在的名称，例如 <code>puzzle</code>、<code>star</code>、<code>package</code>。</li><li>目录插件可以用相对图片路径，例如 <code>&quot;icon&quot;: &quot;icon.png&quot;</code>；jar 插件建议使用内置图标。</li><li>名称拼错时启动器会回退到默认图标，不会导致加载失败。</li></ul><h2 id="插件会影响启动器体积吗" tabindex="-1">插件会影响启动器体积吗 <a class="header-anchor" href="#插件会影响启动器体积吗" aria-label="Permalink to &quot;插件会影响启动器体积吗&quot;">​</a></h2><p>不会。插件是外部文件，不参与启动器打包。启动器本身保持在约 1 MB， 插件按需安装、按需加载。</p><h2 id="如何发布插件" tabindex="-1">如何发布插件 <a class="header-anchor" href="#如何发布插件" aria-label="Permalink to &quot;如何发布插件&quot;">​</a></h2><p>目前通过 zip 分发：</p><ol><li>在仓库 Release 提供 <code>xxx-plugin.zip</code>。</li><li>附上 <code>plugin.json</code>、版本号、兼容的启动器版本和截图。</li><li>建议在仓库 README 标注 <code>tcraft-plugin</code> 主题，方便社区检索。</li></ol><p>插件市场与在线索引还在规划中，完成后会在此文档更新。</p><h2 id="文档里的示例能直接运行吗" tabindex="-1">文档里的示例能直接运行吗 <a class="header-anchor" href="#文档里的示例能直接运行吗" aria-label="Permalink to &quot;文档里的示例能直接运行吗&quot;">​</a></h2><p>可以。每个示例都基于 <code>tcraft.api</code> 的公开 API，按<a href="/TCraft-Launcher/wiki/guide">快速开始</a>编译即可。 遇到文档与启动器不一致时，以 <code>TCraftLauncher.jar</code> 中的 <code>tcraft.api</code> 类为准。</p>',35)])])}const b=e(t,[["render",d]]);export{k as __pageData,b as default};
